begin;do $$begin if current_setting('factorylean.disposable_test',true)is distinct from'true'or inet_server_addr()<>'127.0.0.1'::inet or inet_server_port()in(5432,55496)or current_database()<>'factory_lean_quality_local'then raise exception 'Explicit disposable test target required';end if;end$$;create schema prep_test;create table prep_test.checks(label text);create function prep_test.ok(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;insert into prep_test.checks values(label);end$$;create function prep_test.fails(statement text,code text)returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=code then insert into prep_test.checks values('Rejected '||code);return;end if;raise;end;raise exception 'Expected denial';end$$;
set local request.jwt.claim.sub='53d045ae-2bfe-4acb-8b98-e0e4b11dc81e';

create function prep_test.fixture(label text,inputmode text default 'DIRECT_RAW',autoplan boolean default true)returns jsonb language plpgsql as $$declare f uuid:='3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8';raw uuid;compound uuid;p uuid;b uuid;l uuid;m uuid;cat uuid;so uuid;i uuid;begin
 insert into public.materials(factory_id,name,code,unit)values(f,'Ingredient '||label,'PREP-RAW-'||label,'kg')returning id into raw;
 insert into public.inventory_transactions(factory_id,material_id,quantity,kind,unit,created_by)values(f,raw,100,'opening_balance','kg',auth.uid());
 insert into public.products(factory_id,name,code,unit,stock_unit,product_kind,unit_weight_kg)values(f,'Compound '||label,'PREP-C-'||label,'kg','kg','MANUFACTURED_INTERMEDIATE',1)returning id into compound;
 insert into public.bom_versions(factory_id,product_id,version,batch_quantity,output_unit,created_by)values(f,compound,1,1,'kg',auth.uid())returning id into b;
 insert into public.bom_items(factory_id,bom_id,material_id,quantity,unit)values(f,b,raw,1,'kg');
 insert into public.products(factory_id,name,code,unit,stock_unit,unit_weight_kg,formula_product_id)values(f,'Pipe '||label,'PREP-P-'||label,'meter','meter',.5,compound)returning id into p;
 insert into public.production_lines(factory_id,name,code)values(f,'Material QA '||label,'PREP-L-'||label)returning id into l;
 insert into public.work_center_categories(factory_id,name)values(f,'Material QA '||label)returning id into cat;
 insert into public.work_centers(factory_id,name,code,line_id,category_id,status,dependency_mode,impact_scope)values(f,'Processor '||label,'PREP-M-'||label,l,cat,'running','blocking','whole_line')returning id into m;
 insert into public.work_center_capabilities(factory_id,work_center_id,product_id,rate,rate_unit,setup_minutes)values(f,m,p,6000,'meter',0);
 insert into public.production_routing_steps(factory_id,product_id,position,kind,work_center_id)values(f,p,1,'work_center',m);
 so:=public.create_sales_order(f,jsonb_build_object('customer_reference','Material QA '||label,'lines',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',20,'unit','meter'))),gen_random_uuid());perform public.approve_sales_order(f,so,gen_random_uuid());select id into i from public.production_orders where factory_id=f and product_id=p;
 if not autoplan then return jsonb_build_object('factory',f,'item',i,'product',p,'compound',compound,'raw',raw,'line',l,'machine',m,'sales',so);end if;
 perform public.configure_production_materials(f,'ROUTE',jsonb_build_object('product',p,'mode',inputmode),gen_random_uuid());
 perform public.plan_product_item(f,i,l,clock_timestamp()+interval '15 seconds');return jsonb_build_object('factory',f,'item',i,'product',p,'compound',compound,'raw',raw,'line',l,'machine',m,'sales',so);end$$;
do $$declare x jsonb;f uuid:='3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8';r uuid;s jsonb;k uuid;v int;n int;begin
 x:=prep_test.fixture('lifecycle');perform private.process_material_preparation(f);select id into r from public.material_requests where factory_id=f and production_item_id=(x->>'item')::uuid;perform prep_test.ok(r is not null,'automatic request created');perform prep_test.ok((select quantity=10 and status='REQUESTED'and requested_by is null and requested_by_name='System'from public.material_requests where id=r),'single stage raw requirement with system provenance');perform prep_test.ok((select reserved=0 and issued=0 from private.material_request_progress where request_id=r),'creation never reserves/issues');perform private.process_material_preparation(f);perform prep_test.ok((select count(*)=1 from public.material_requests where production_item_id=(x->>'item')::uuid),'repeated worker creates no duplicate');
 select revision into v from public.material_requests where id=r;k:=gen_random_uuid();s:=public.production_material_action(f,'RESERVE',jsonb_build_object('id',r,'revision',v,'quantity','4'),k);perform prep_test.ok((s->>'reserved')::numeric=4,'partial raw reservation');perform prep_test.ok((select sum(quantity)=100 from public.inventory_transactions where material_id=(x->>'raw')::uuid),'reservation preserves on hand');perform prep_test.ok(s=public.production_material_action(f,'RESERVE',jsonb_build_object('id',r,'revision',v,'quantity','4'),k),'reservation UUID replay');
 select revision into v from public.material_requests where id=r;s:=public.production_material_action(f,'ISSUE',jsonb_build_object('id',r,'revision',v,'quantity','2','physical_confirmation',true),gen_random_uuid());perform prep_test.ok((s->>'reserved')::numeric=2 and(s->>'issued')::numeric=2 and(s->>'consumed')::numeric=0,'partial handover not consumption');perform prep_test.ok((select sum(quantity)=98 from public.inventory_transactions where material_id=(x->>'raw')::uuid),'issue deducts warehouse once');
 perform prep_test.fails(format('select public.supply_command(%L,%L,%L,%L)',f,'material_change',jsonb_build_object('id',r,'revision',v,'action','issue'),gen_random_uuid()),'22023');
 perform private.release_material_preparation(f,(x->>'item')::uuid);perform prep_test.ok((select reserved=0 and issued=2 and consumed=0 and awaiting from private.material_request_progress where request_id=r),'postponement releases only unissued reserved');perform prep_test.ok((select sum(quantity)=98 from public.inventory_transactions where material_id=(x->>'raw')::uuid),'release never returns issued stock');
 perform private.process_material_preparation(f);perform prep_test.ok((select not awaiting from private.material_request_progress where request_id=r),'same request reactivated');perform prep_test.ok((select count(*)=1 from public.material_requests where production_item_id=(x->>'item')::uuid),'reactivation retains identity');
end$$;

do $$declare x jsonb;f uuid:='3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8';r uuid;s jsonb;v int;k uuid;n int;ctx jsonb;before jsonb;begin
 x:=prep_test.fixture('boundaries');select id into r from public.material_requests where production_item_id=(x->>'item')::uuid;perform prep_test.ok(r is not null,'planning commit creates prompt request without worker');
 select revision into v from public.material_requests where id=r;perform prep_test.fails(format('select public.production_material_action(%L,%L,%L,%L)',f,'RESERVE',jsonb_build_object('id',r,'revision',v,'quantity','101'),gen_random_uuid()),'22023');
 s:=public.production_material_action(f,'RESERVE',jsonb_build_object('id',r,'revision',v,'quantity','10'),gen_random_uuid());perform prep_test.ok((s->>'reserved')::numeric=10,'full reserve uses only required amount');
 select revision into v from public.material_requests where id=r;perform prep_test.fails(format('select public.production_material_action(%L,%L,%L,%L)',f,'ISSUE',jsonb_build_object('id',r,'revision',v,'quantity','2'),gen_random_uuid()),'22023');
 s:=public.production_material_action(f,'ISSUE',jsonb_build_object('id',r,'revision',v,'quantity','2','physical_confirmation',true),gen_random_uuid());perform prep_test.ok(private.planning_issued_time_change_safe(f,(x->>'item')::uuid),'identified zero-consumption custody permits same-line time revision');
 ctx:=public.planning_change_context(f,(x->>'item')::uuid);perform public.revise_product_plan_confirmed(f,(x->>'item')::uuid,(x->>'line')::uuid,clock_timestamp()+interval '2 days','material_delay','Postpone test with real custody',ctx->>'fingerprint',true,gen_random_uuid());
 perform prep_test.ok((select reserved=0 and issued=2 and awaiting from private.material_request_progress where request_id=r),'real protected postponement releases only remaining eight');perform prep_test.ok((select sum(quantity)=98 from public.inventory_transactions where material_id=(x->>'raw')::uuid),'real postponement has no phantom stock return');
 select revision into v from public.material_requests where id=r;s:=public.production_material_action(f,'RETURN',jsonb_build_object('id',r,'revision',v,'quantity','1','physical_confirmation',true,'reason','Measured unused material returned'),gen_random_uuid());perform prep_test.ok((s->>'issued')::numeric=1 and(select sum(quantity)=99 from public.inventory_transactions where material_id=(x->>'raw')::uuid),'only physical return restores stock');
 select revision into v from public.material_requests where id=r;perform set_config('request.jwt.claim.sub','4dea0a6e-971b-4d77-b3de-da494a1b5cd6',true);perform prep_test.fails(format('select public.production_material_action(%L,%L,%L,%L)',f,'RETURN',jsonb_build_object('id',r,'revision',v,'quantity','1','physical_confirmation',true,'reason','No Warehouse authority'),gen_random_uuid()),'42501');
 perform prep_test.fails(format('select public.production_material_work(%L,%L,null)',gen_random_uuid(),'WAREHOUSE'),'42501');perform set_config('request.jwt.claim.sub','53d045ae-2bfe-4acb-8b98-e0e4b11dc81e',true);
 perform prep_test.ok((public.production_material_work(f,'WAREHOUSE',(x->>'item')::uuid)->'rows'->0->>'issued')::numeric=1,'Warehouse protected read shows issued custody');
 select count(*)into n from jsonb_array_elements(public.planning_changes_read(f,'WAREHOUSE')->'rows')e where e->>'code'=(select code from public.production_orders where id=(x->>'item')::uuid);perform prep_test.ok(n>=3,'Warehouse sees request and affected-plan/release events');

end$$;
do $$declare x jsonb;f uuid:='3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8';r uuid;s jsonb;v int;k uuid;payload jsonb;n int;begin
 x:=prep_test.fixture('consume');select id into r from public.material_requests where production_item_id=(x->>'item')::uuid;
 select revision into v from public.material_requests where id=r;perform public.production_material_action(f,'RESERVE',jsonb_build_object('id',r,'revision',v,'quantity','10'),gen_random_uuid());select revision into v from public.material_requests where id=r;perform public.production_material_action(f,'ISSUE',jsonb_build_object('id',r,'revision',v,'quantity','10','physical_confirmation',true),gen_random_uuid());
 perform public.start_product_item(f,(x->>'item')::uuid);select revision into v from public.material_requests where id=r;k:=gen_random_uuid();payload:=jsonb_build_object('id',r,'revision',v,'quantity','8');s:=public.production_material_action(f,'CONSUME',payload,k);perform prep_test.ok((s->>'consumed')::numeric=8 and(s->>'issued')::numeric=10,'actual measured consumption separate from custody');perform prep_test.ok(s=public.production_material_action(f,'CONSUME',payload,k),'consumption UUID retries once');perform prep_test.ok((select sum(quantity)=90 from public.inventory_transactions where material_id=(x->>'raw')::uuid),'consumption never deducts stock twice');
 select revision into v from public.material_requests where id=r;perform prep_test.fails(format('select public.production_material_action(%L,%L,%L,%L)',f,'RETURN',jsonb_build_object('id',r,'revision',v,'quantity','3','physical_confirmation',true,'reason','Too much after use'),gen_random_uuid()),'22023');perform prep_test.ok(not private.planning_issued_time_change_safe(f,(x->>'item')::uuid),'consumed/active material cannot use unstarted custody exception');
 select count(*)into n from private.material_preparation_events where request_id=r and operation='CONSUME';perform prep_test.ok(n=1,'one immutable consumption event');
end$$;
do $$declare x jsonb;f uuid:='3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8';r uuid;s jsonb;v int;before numeric;begin
 x:=prep_test.fixture('missing');delete from private.production_input_routes where factory_id=f and product_id=(x->>'product')::uuid;
 -- Remove only this disposable fixture's untouched generated request to model an unconfigured first schedule.
 delete from private.material_preparation_events where false;
 select sum(quantity)into before from public.inventory_transactions where material_id=(x->>'raw')::uuid;
 perform private.process_material_preparation(f);perform prep_test.ok((select warning='material_route_missing'from private.material_preparation_jobs where factory_id=f and item_id=(x->>'item')::uuid),'missing physical route warns without speculative new input');perform prep_test.ok((select sum(quantity)=before from public.inventory_transactions where material_id=(x->>'raw')::uuid),'missing route never changes inventory');
end$$;
do $$declare f uuid:='3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8';e uuid;n int;begin select (x->>'request_id')::uuid into e from jsonb_array_elements(public.planning_changes_read(f,'PRODUCTION')->'rows')x where x->>'material_operation'='ISSUE'limit 1;perform prep_test.ok(e is not null,'Production receives physical issue notification');perform public.acknowledge_planning_change(f,e,'PRODUCTION');perform public.acknowledge_planning_change(f,e,'PRODUCTION');perform prep_test.ok((select count(*)=1 from private.material_preparation_acknowledgments where event_id=e and user_id=auth.uid()),'acknowledgment retries once');end$$;
-- The shift is a rollback-only fixture, not an owner configuration change.
do $$declare x record;begin for x in select *from public.production_shifts where factory_id='3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8'and not archived loop perform public.configure_production_shift(x.factory_id,x.name,x.name_ar,x.start_time,x.end_time,x.id,true);end loop;end$$;
select public.configure_production_shift('3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8','Material preparation acceptance','اختبار تجهيز المواد',(clock_timestamp()+interval '1 second')::time,(clock_timestamp()+interval '1 hour')::time);
select pg_sleep(1.2);
create function prep_test.produce(x jsonb,q numeric)returns jsonb language plpgsql as $$declare f uuid:=(x->>'factory')::uuid;r jsonb;h private.manufactured_outputs;g jsonb;w uuid;sid uuid;begin
 if (select status from public.production_orders where id=(x->>'item')::uuid)<>'active'then perform public.start_product_item(f,(x->>'item')::uuid);end if;r:=public.record_manufactured_output(f,output2_test.payload(x,q),gen_random_uuid());select *into h from private.manufactured_outputs where entry_id=(r->>'entry_id')::uuid;
 select jsonb_agg(value||jsonb_build_object('released',value->>'quantity'))into g from jsonb_array_elements(h.recorded_groups);perform public.manufactured_output_command(f,'QUALITY',h.id,jsonb_build_object('groups',g,'rejected','0','actual_rejected_kg','0','reason','Measured controlled material workflow inspection'),1,gen_random_uuid());select id into w from public.factory_warehouses where factory_id=f and active and storage_class='FINISHED'order by id limit 1;
 perform public.receive_manufactured_output(f,h.id,jsonb_build_object('group_id',g->0->>'id','quantity',q::text,'warehouse_id',w,'physical_confirmation',true,'note','Physically identified local material acceptance'),2,gen_random_uuid());select id into sid from public.finished_goods_sources where factory_id=f and entry_id=h.entry_id;
 perform public.source_stock_command(f,'identify',jsonb_build_object('source',sid,'quantity',q::text,'label','Material QA batch '||h.id,'physically_identified',true,'note','Separate identified controlled production batch'),'[]',gen_random_uuid());
 return jsonb_build_object('entry',h.entry_id,'output',h.id,'source',sid);end$$;
do $$declare x jsonb;f uuid:='3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8';r uuid;v int;s jsonb;out jsonb;k uuid;p jsonb;sl uuid;before_good numeric;begin
 x:='{"lot":"984b4f41-0bb4-41b1-bd8c-2d8ed054ec84","drag":"19405f2e-27e4-44d7-842b-d6bfcb4fb626","form":"4afef1ed-2824-4c8a-ac4a-2a048142bbb8","item":"75dd274d-c878-4e20-8fc1-2d12dcb40998","line":"209e68de-bbce-4dc0-ac2d-09cf69ed77ad","group":"8622f7b6-d4d6-4587-afac-942eb79a4b11","owner":"53d045ae-2bfe-4acb-8b98-e0e4b11dc81e","shift":"5999f47e-6175-444a-8956-22e19d31bfa2","step1":"403b9bc3-188c-4faa-ad5e-8c19e51032c4","step2":"13f1cae5-f2b5-40be-8916-5d1a30a3c650","locked":"1d0742aa-cab6-4e62-b1e7-7eb51371a0ef","output":"74bfc718-4346-4eba-b9cc-76155dd4d385","viewer":"24511dcc-4e59-4973-881a-b9c02ffe535e","worker":"4dea0a6e-971b-4d77-b3de-da494a1b5cd6","factory":"3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8","machine":"14b58a7e-0594-4db1-a422-a8ca4a7032ff","product":"8980e5b8-4f72-4458-afe8-931a15cd90b8","request":"5f0f2060-6c2d-46f1-a2fa-c0fca3bda172","recovery":"50922e50-03a4-4c0f-8d6c-fe63faf38390","revision":4,"other_line":"5adeb6a6-0e47-43e4-8a65-ae9dbee25eb3","independent":"d4ce17b9-2d7e-4446-8ccd-dba37b2c5ff4","invalid_line":"8850ff34-3362-4cc2-ab91-71a6a953ecbe","other_machine":"2b47a04d-43b6-4cb1-a8a5-77c3b55140a8"}'::jsonb||prep_test.fixture('e2e');select id into r from public.material_requests where production_item_id=(x->>'item')::uuid;select revision into v from public.material_requests where id=r;
 perform public.production_material_action(f,'RESERVE',jsonb_build_object('id',r,'revision',v,'quantity','10'),gen_random_uuid());select revision into v from public.material_requests where id=r;perform public.production_material_action(f,'ISSUE',jsonb_build_object('id',r,'revision',v,'quantity','10','physical_confirmation',true),gen_random_uuid());
 perform public.start_product_item(f,(x->>'item')::uuid);select revision into v from public.material_requests where id=r;perform public.production_material_action(f,'CONSUME',jsonb_build_object('id',r,'revision',v,'quantity','10'),gen_random_uuid());
 -- produce() starts through the idempotent normal Start contract.
 out:=prep_test.produce(x,20);perform prep_test.ok((select effective_good=20 and effective_scrap_kg=0 from public.production_entries where id=(out->>'entry')::uuid),'normal Sales->Production->Good->Quality->Warehouse path');
 select id into sl from public.sales_order_lines where order_id=(x->>'sales')::uuid;perform prep_test.ok((select quantity=20 from public.finished_goods_reservations where line_id=sl),'Sales reservation receives accepted stock once');
 k:=gen_random_uuid();p:=jsonb_build_object('sales_order',x->>'sales','line',sl);perform public.source_stock_command(f,'dispatch',p,jsonb_build_array(jsonb_build_object('sales_line_id',sl,'source_id',out->>'source','quantity','20')),k);perform public.source_stock_command(f,'dispatch',p,jsonb_build_array(jsonb_build_object('sales_line_id',sl,'source_id',out->>'source','quantity','20')),k);
 perform prep_test.ok((select dispatched_quantity=20 from public.sales_order_lines where id=sl),'Sales dispatch idempotent fulfillment');perform prep_test.ok((select on_hand=0 and reserved=0 from public.finished_goods_balances where product_id=(x->>'product')::uuid),'no duplicate receipt/dispatch or negative finished stock');perform prep_test.ok((select sum(quantity)=90 from public.inventory_transactions where material_id=(x->>'raw')::uuid),'raw issued exactly once through complete E2E');perform prep_test.ok((select consumed=10 and issued=10 and reserved=0 from private.material_request_progress where request_id=r),'complete E2E custody conservation');
end$$;

do $$declare x jsonb;f uuid:='3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8';l uuid;cat uuid;machine uuid;req uuid;i uuid;step uuid;w jsonb;out jsonb;r uuid;v int;s jsonb;sid uuid;picks jsonb;k uuid;payload jsonb;begin
 x:='{"lot":"984b4f41-0bb4-41b1-bd8c-2d8ed054ec84","drag":"19405f2e-27e4-44d7-842b-d6bfcb4fb626","form":"4afef1ed-2824-4c8a-ac4a-2a048142bbb8","item":"75dd274d-c878-4e20-8fc1-2d12dcb40998","line":"209e68de-bbce-4dc0-ac2d-09cf69ed77ad","group":"8622f7b6-d4d6-4587-afac-942eb79a4b11","owner":"53d045ae-2bfe-4acb-8b98-e0e4b11dc81e","shift":"5999f47e-6175-444a-8956-22e19d31bfa2","step1":"403b9bc3-188c-4faa-ad5e-8c19e51032c4","step2":"13f1cae5-f2b5-40be-8916-5d1a30a3c650","locked":"1d0742aa-cab6-4e62-b1e7-7eb51371a0ef","output":"74bfc718-4346-4eba-b9cc-76155dd4d385","viewer":"24511dcc-4e59-4973-881a-b9c02ffe535e","worker":"4dea0a6e-971b-4d77-b3de-da494a1b5cd6","factory":"3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8","machine":"14b58a7e-0594-4db1-a422-a8ca4a7032ff","product":"8980e5b8-4f72-4458-afe8-931a15cd90b8","request":"5f0f2060-6c2d-46f1-a2fa-c0fca3bda172","recovery":"50922e50-03a4-4c0f-8d6c-fe63faf38390","revision":4,"other_line":"5adeb6a6-0e47-43e4-8a65-ae9dbee25eb3","independent":"d4ce17b9-2d7e-4446-8ccd-dba37b2c5ff4","invalid_line":"8850ff34-3362-4cc2-ab91-71a6a953ecbe","other_machine":"2b47a04d-43b6-4cb1-a8a5-77c3b55140a8"}'::jsonb||prep_test.fixture('compound-route','COMPOUND_STOCK');select id into r from public.material_requests where production_item_id=(x->>'item')::uuid;perform prep_test.ok((select product_id=(x->>'compound')::uuid and material_id is null and quantity=10 from public.material_requests where id=r),'compound stock route requests only physical compound');perform prep_test.ok((select count(*)=1 from public.material_requests where production_item_id=(x->>'item')::uuid),'no duplicate raw ingredient request for compound stage');
 insert into public.production_lines(factory_id,name,code)values(f,'QA Compound processor','QA-COMPOUND')returning id into l;insert into public.work_center_categories(factory_id,name)values(f,'QA Compound processor')returning id into cat;insert into public.work_centers(factory_id,name,code,line_id,category_id,status,dependency_mode,impact_scope)values(f,'QA Compound mixer','QA-MIXER',l,cat,'running','blocking','whole_line')returning id into machine;insert into public.work_center_capabilities(factory_id,work_center_id,product_id,rate,rate_unit,setup_minutes)values(f,machine,(x->>'compound')::uuid,1000,'kg',0);insert into public.production_routing_steps(factory_id,product_id,position,kind,work_center_id)values(f,(x->>'compound')::uuid,1,'work_center',machine)returning id into step;
 req:=public.create_production_request(f,'QA Compound stock preparation','normal',null,'Controlled material source fixture',jsonb_build_array(jsonb_build_object('product_id',x->>'compound','quantity',20,'unit','kg')));select id into i from public.production_orders where request_id=req;perform public.configure_production_materials(f,'ROUTE',jsonb_build_object('product',x->>'compound','mode','COMPOUND_MANUFACTURE'),gen_random_uuid());perform public.plan_product_item(f,i,l,clock_timestamp()+interval '1 second');
 select id into req from public.material_requests where production_item_id=i;perform prep_test.ok((select material_id=(x->>'raw')::uuid and quantity=20 from public.material_requests where id=req),'compound manufacture requests own raw ingredients');select revision into v from public.material_requests where id=req;perform public.production_material_action(f,'RESERVE',jsonb_build_object('id',req,'revision',v,'quantity','20'),gen_random_uuid());select revision into v from public.material_requests where id=req;perform public.production_material_action(f,'ISSUE',jsonb_build_object('id',req,'revision',v,'quantity','20','physical_confirmation',true),gen_random_uuid());perform public.start_product_item(f,i);select revision into v from public.material_requests where id=req;perform public.production_material_action(f,'CONSUME',jsonb_build_object('id',req,'revision',v,'quantity','20'),gen_random_uuid());out:=prep_test.produce(x||jsonb_build_object('item',i,'line',l,'product',x->>'compound','step1',step,'step2',step),20);perform public.finish_product_item(f,i);sid:=(out->>'source')::uuid;
 select revision into v from public.material_requests where id=r;picks:=jsonb_build_array(jsonb_build_object('source_id',sid,'quantity','6'));perform public.production_material_action(f,'RESERVE',jsonb_build_object('id',r,'revision',v,'quantity','6','allocations',picks),gen_random_uuid());perform prep_test.ok((select on_hand=20 and reserved=6 from public.finished_goods_balances where product_id=(x->>'compound')::uuid),'compound reserve changes available only');
 select revision into v from public.material_requests where id=r;k:=gen_random_uuid();payload:=jsonb_build_object('id',r,'revision',v,'quantity','4','physical_confirmation',true,'allocations',jsonb_build_array(jsonb_build_object('source_id',sid,'quantity','4')));s:=public.production_material_action(f,'ISSUE',payload,k);perform prep_test.ok(s=public.production_material_action(f,'ISSUE',payload,k),'compound issue retry returns original receipt');perform prep_test.ok((select on_hand=16 and reserved=2 from public.finished_goods_balances where product_id=(x->>'compound')::uuid),'compound partial issue stock/source conservation');
 select revision into v from public.material_requests where id=r;perform public.production_material_action(f,'RETURN',jsonb_build_object('id',r,'revision',v,'quantity','1','physical_confirmation',true,'reason','Unused identified compound returned','allocations',jsonb_build_array(jsonb_build_object('source_id',sid,'quantity','1'))),gen_random_uuid());perform prep_test.ok((select on_hand=17 and reserved=2 from public.finished_goods_balances where product_id=(x->>'compound')::uuid),'compound return restores same identified source');
 perform public.start_product_item(f,(x->>'item')::uuid);select revision into v from public.material_requests where id=r;perform public.production_material_action(f,'CONSUME',jsonb_build_object('id',r,'revision',v,'quantity','3','allocations',jsonb_build_array(jsonb_build_object('source_id',sid,'quantity','3'))),gen_random_uuid());perform prep_test.ok((select quantity=3 and consumed=3 from private.material_source_custody where request_id=r),'identified compound actual use retains source genealogy');perform prep_test.ok((select on_hand=17 from public.finished_goods_balances where product_id=(x->>'compound')::uuid),'compound consumption deducts no second stock');
 set constraints all immediate;perform prep_test.ok(true,'deferred source conservation passes including physical return');
end$$;

do $$declare x jsonb;f uuid:='3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8';r uuid;a uuid;s jsonb;v int;n int;begin
 x:=prep_test.fixture('manual','DIRECT_RAW',false);r:=public.supply_command(f,'material_request',jsonb_build_object('item',x->>'raw','item_type','material','unit','kg','quantity','4','production_item_id',x->>'item','note','Explicit known physical raw input'),gen_random_uuid());perform public.plan_product_item(f,(x->>'item')::uuid,(x->>'line')::uuid,clock_timestamp()+interval '1 hour');
 perform prep_test.ok((select count(*)=1 from public.material_requests where production_item_id=(x->>'item')::uuid),'missing configuration creates no automatic demand alongside manual request');
 select revision into v from public.material_requests where id=r;perform public.production_material_action(f,'RESERVE',jsonb_build_object('id',r,'revision',v,'quantity','4'),gen_random_uuid());perform prep_test.ok((select reserved=4 from private.material_request_progress where request_id=r),'explicit manual material can reserve despite missing automatic route');
 perform public.configure_production_materials(f,'ROUTE',jsonb_build_object('product',x->>'product','mode','DIRECT_RAW'),gen_random_uuid());perform private.process_material_preparation(f);select id into a from public.material_requests where production_item_id=(x->>'item')::uuid and automatic_requirement_key is not null;perform prep_test.ok((select quantity=6 from public.material_requests where id=a),'automatic preparation requests only remainder after manual quantity');
 select revision into v from public.material_requests where id=a;perform prep_test.fails(format('select public.production_material_action(%L,%L,%L,%L)',f,'RESERVE',jsonb_build_object('id',a,'revision',v-1,'quantity','1'),gen_random_uuid()),'40001');
 perform public.supply_command(f,'material_request',jsonb_build_object('item',x->>'raw','item_type','material','unit','kg','quantity','1','production_item_id',x->>'item','note','Changed manual demand requires review'),gen_random_uuid());perform prep_test.fails(format('select public.production_material_action(%L,%L,%L,%L)',f,'RESERVE',jsonb_build_object('id',a,'revision',v,'quantity','1'),gen_random_uuid()),'22023');perform prep_test.ok((select reserved=0 from private.material_request_progress where request_id=a),'ambiguous changed requirements never reserve extra stock');
 perform prep_test.fails(format('update private.material_preparation_events set operation=%L where request_id=%L','RESERVE',r),'42501');
end$$;
do $$declare x jsonb;f uuid:='3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8';begin x:=prep_test.fixture('natural','DIRECT_RAW',false);perform public.configure_production_materials(f,'ROUTE',jsonb_build_object('product',x->>'product','mode','DIRECT_RAW'),gen_random_uuid());perform public.configure_production_materials(f,'WINDOW',jsonb_build_object('hours','0.0003'),gen_random_uuid());perform public.plan_product_item(f,(x->>'item')::uuid,(x->>'line')::uuid,clock_timestamp()+interval '2 seconds');perform prep_test.ok(not exists(select 1 from public.material_requests where production_item_id=(x->>'item')::uuid),'future start outside separate preparation window remains unrequested');perform pg_sleep(1.3);perform set_config('request.jwt.claim.sub','',true);perform private.process_material_preparation(f);perform prep_test.ok((select count(*)=1 from public.material_requests where production_item_id=(x->>'item')::uuid),'natural time entry runs without browser actor');perform set_config('request.jwt.claim.sub','53d045ae-2bfe-4acb-8b98-e0e4b11dc81e',true);perform public.configure_production_materials(f,'WINDOW',jsonb_build_object('hours','6'),gen_random_uuid());end$$;
select prep_test.ok(not has_function_privilege('authenticated','private.process_material_preparation(uuid)','EXECUTE'),'browser cannot invoke privileged scheduler');select prep_test.ok(not has_table_privilege('authenticated','private.material_request_progress','UPDATE'),'progress table not client writable');
do $$declare f uuid:='3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8';x jsonb;r uuid;v int;rows jsonb;begin x:=prep_test.fixture('queue');select id into r from public.material_requests where production_item_id=(x->>'item')::uuid;select revision into v from public.material_requests where id=r;perform public.production_material_action(f,'RESERVE',jsonb_build_object('id',r,'revision',v,'quantity','4'),gen_random_uuid());select revision into v from public.material_requests where id=r;perform public.production_material_action(f,'ISSUE',jsonb_build_object('id',r,'revision',v,'quantity','1','physical_confirmation',true),gen_random_uuid());rows:=public.supply_page(f,'materials',1);perform prep_test.ok(exists(select 1 from jsonb_array_elements(rows->'rows')m where m->>'id'=r::text and m#>>'{preparation,status}'='PARTIALLY_ISSUED'and m->>'code'=(select code from public.production_orders where id=(x->>'item')::uuid)),'existing counted Warehouse request reader preserves partial issue and Production Order link');end$$;select jsonb_build_object('count',count(*),'assertions',jsonb_agg(label))from prep_test.checks;rollback;